WITH enriched AS (SELECT *, NTILE(3) OVER (PARTITION BY region ORDER BY sqft DESC, id) AS sqft_bucket, LEAD(sqft, 1) OVER (PARTITION BY region ORDER BY opened_date, id) AS next_sqft, AVG(sqft) OVER (PARTITION BY MONTH(opened_date) ORDER BY opened_date, id ROWS BETWEEN 3 PRECEDING AND 1 PRECEDING) AS sqft_avg_3_prior FROM stores) SELECT city, CASE WHEN sqft_bucket >= 8 THEN 'HIGH' ELSE 'LOW' END AS sqft_bucket_tier, COUNT(DISTINCT city) AS distinct_cities, SORT_ARRAY(COLLECT_SET(city)) AS city_list, PERCENTILE_APPROX(sqft_bucket, ARRAY(0.25, 0.5, 0.75)) AS sqft_bucket_quartiles, AVG(sqft_bucket) FILTER (WHERE region = 'East') AS east_avg_sqft_bucket, COUNT_IF(region = 'North') AS north_events, COUNT(*) FILTER (WHERE region = 'North') AS north_rows FROM enriched GROUP BY CUBE (city, CASE WHEN sqft_bucket >= 8 THEN 'HIGH' ELSE 'LOW' END) HAVING AVG(sqft_bucket) FILTER (WHERE region = 'East') > 0 ORDER BY north_events;
